------------ import ------------
local KTool = CS.Engine.Lib.KTool
local support = require('Frame.support')
local cs_coroutine = require('XLua.cs_coroutine')
local Yielders = CS.Engine.Lib.Yielders
local Time = CS.UnityEngine.Time
local XLuaUtils = CS.Engine.Lib.XLuaUtils
local AnimationCurve = CS.UnityEngine.AnimationCurve
local Keyframe = CS.UnityEngine.Keyframe
------------ import ------------


------------ define ------------
local UILineRenderer = typeof(CS.UnityEngine.UI.Extensions.UILineRenderer)
local UnityVector2 = typeof(CS.UnityEngine.Vector2)

local quaterAngle = 90              -- 圆弧部分的角度
local quaterPointNum = 10            -- 圆弧部分使用几个控制点
local linePointNum = 2              -- 直线部分使用几个控制点
local originPos = Vector2.New(-2.6,0)  -- slider相对起始点的坐标偏移
------------ define ------------

local BossSlider = Class("BossSlider")

------------ lifeCycle ------------
function BossSlider:Awake()
    self.quaterRadiur = 48          -- 圆弧部分的半径
    self.lineLength = 384           -- 直线部分的长度
    self.width = 20                 -- slider的宽度
    self.isReverseMode = false      -- 是否是反向增长的slider
    -- self.defaultCurve = CS.UnityEngine.AnimationCurve.EaseInOut(0, 0, 1, 1)
    self.defaultCurve = AnimationCurve()
    self.defaultCurve:AddKey(Keyframe(0,0,3,3))
    self.defaultCurve:AddKey(Keyframe(1,1,0,0))

    self.uiLineRenderer = nil
    self.quaterPercentage = nil     -- 弯曲部分占整根slider的比例
    self.circleCenterPos = nil      -- 圆弧部分的圆心坐标
    self.lineStartPos = nil         -- 直线部分和圆弧相连的起点
    self.lineEndPos = nil           -- 直线部分的终点
    self.pointList = nil            -- 保存控制点的数组
    self.progress = nil             -- slider的进度
    self.lerpCo = nil               -- lerp进度的协程
    self.lerpToValue = nil          -- 要lerp到的progress
    self.commandQueue = nil         -- 延迟队列
    self.delayLerpCo = nil          -- 延迟lerp协程
    self.delayCommandCoArray = nil  -- 插值数组
    self.delayCommandCo2 = nil      -- 延迟命令携程 类型2使用

    self:Init()
end

function BossSlider:OnDestroy()
    self:StopCo()

    self.defaultCurve = nil
    self.uiLineRenderer = nil
    self.quaterPercentage = nil     -- 弯曲部分占整根slider的比例
    self.circleCenterPos = nil      -- 圆弧部分的圆心坐标
    self.lineStartPos = nil         -- 直线部分和圆弧相连的起点
    self.lineEndPos = nil           -- 直线部分的终点
    self.pointList = nil            -- 保存控制点的数组
    self.progress = nil             -- slider的进度
    self.lerpCo = nil               -- lerp进度的协程
    self.lerpToValue = nil          -- 要lerp到的progress
    self.commandQueue = nil         -- 延迟队列
    self.delayLerpCo = nil          -- 延迟lerp协程
    self.delayCommandCoArray = nil  -- 插值数组
    self.delayCommandCo2 = nil      -- 延迟命令携程 类型2使用
end

function BossSlider:StopCo()
    if not isNull(self.delayCommandCoArray) then
        for k, v in pairs(self.delayCommandCoArray) do
            if not isNull(v) then
                cs_coroutine.stop(v)
                self.delayCommandCoArray[k] = nil
            end
        end
        self.delayCommandCoArray = {}
    end
    if not isNull(self.delayLerpCo) then
        cs_coroutine.stop(self.delayLerpCo)
        self.delayLerpCo = nil
    end
    if not isNull(self.delayCommandCo2) then
        cs_coroutine.stop(self.delayCommandCo2)
        self.delayCommandCo2 = nil
    end
    self:StopLerpProgress()
end
------------ lifeCycle ------------

function BossSlider:Init()
    -- 弯曲部分占整根slider的比例
    local quaterLength = self.quaterRadiur * 1.5
    self.quaterPercentage = quaterLength / (quaterLength + self.lineLength)
    self.uiLineRenderer = self.controller.gameObject:GetComponent(typeof(UILineRenderer))
    self.pointList = support.new_list(typeof(UnityVector2))
end

--- 初始化血条参数
---@param quaterRadiur number 圆弧部分的半径
---@param lineLength number 直线部分的长度
---@param width number slider的宽度
---@param isReverseMode boolean 是否是反向增长的slider
function BossSlider:InitSlider(quaterRadiur, lineLength, width, isReverseMode, originOffset)
    self.quaterRadiur = quaterRadiur
    local quaterLength = self.quaterRadiur * 1.5
    self.quaterPercentage = quaterLength / (quaterLength + self.lineLength)
    self.lineLength = lineLength
    self.width = width
    self.isReverseMode = isReverseMode
    self.originPos = originOffset or originPos
    self:SetPoints()
    return self
end

function BossSlider:SetColor(colorCode)
    self.uiLineRenderer.color = XLuaUtils.HexToColor(colorCode)
end

function BossSlider:GetProgress()
    return self.progress
end

--- 设置slider的进度
---@param progress number (range(0,1))
function BossSlider:SetProgress(progress)
    self:StopCo()

    local point = self:CalculateEndPoint(progress)
    self:SetEndPoint(point)

    self.progress = progress
end

--@region 一般插值

--- 按曲线插值到指定的progress
---@param progress number (range(0.1))进度
---@param duration number 持续时间
---@param curve UnityEngine.AnimationCurve 曲线
function BossSlider:LerpProgress(progress, duration, curve, onLerp, onLerpEnd)
    -- print("[血条] do lerp")
    self:StopLerpProgress()
    self.lerpToValue = progress     -- 结束值缓存下来，强制结束的时候会用到

    local timer = 0
    local duration = duration
    local fromValue = self.progress
    local toValue = progress
    local curve = curve
    
    self.lerpCo = cs_coroutine.start(function()
        while true do
            local t = timer / duration
            if t >= 1 then
                local point = self:CalculateEndPoint(toValue)
                self:SetEndPoint(point)
                self.progress = toValue
                if onLerpEnd ~= nil then
                    onLerpEnd()
                end
                self.lerpCo = nil
                return
            else
                timer = timer + Time.deltaTime
                local p = Mathf.Lerp(fromValue, toValue, curve:Evaluate(t))
                local point = self:CalculateEndPoint(p)
                self:SetEndPoint(point)
                self.progress = p
                if onLerp ~= nil then
                    onLerp()
                end
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
        end
    end)
end

function BossSlider:StopLerpProgress()
    if not isNull(self.lerpCo) then
        cs_coroutine.stop(self.lerpCo)
        self.lerpCo = nil
    end
end

--- 强制结束lerp，直接设置progress到结束位置(目前两种延迟模式不支持使用这个接口)
function BossSlider:ForceOverLerp()
    self:SetProgress(self.lerpToValue)
end
--@endregion

--@region 延迟插值 类型1
-- 每一次调用都在delay时间后，被封装成一个命令，装进命令队列
-- 命令队列里的命令会依次执行，完整执行完上一个命令才会开始下一个命令

--- 延迟插值（不要和普通插值混用）
---@param toProgress any
---@param delay any
---@param duration any
---@param onLerp any
---@param onLerpEnd any
function BossSlider:DelayLerpProgress(toProgress, delay, duration, onLerp, onLerpEnd)
    local command = {
        to = toProgress,
        delay = delay,
        duration = duration,
        onLerp = onLerp,
        onLerpEnd = onLerpEnd,
    }

    local co
    co = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(delay))
        if isNull(self.commandQueue) then
            self.commandQueue = {}
        end
        table.insert(self.commandQueue, command)
        -- print("[血条] insert command")
        self:DoCommand()
        co = nil
    end)

    if isNull(self.delayCommandCoArray) then
        self.delayCommandCoArray = {}
    end
    table.insert(self.delayCommandCoArray, co)
end

function BossSlider:DoCommand()
    if not isNull(self.delayLerpCo) then return end

    self.delayLerpCo = cs_coroutine.start(function()
        while #self.commandQueue > 0 do
            local command = table.remove(self.commandQueue, 1)
            self:LerpProgress(command.to, command.duration, self.defaultCurve, command.onLerp, command.onLerpEnd)
            while not isNull(self.lerpCo) do
                cs_coroutine.yield_return()
            end
        end
        self.delayLerpCo = nil
    end)
end
--@endregion

--@region 延迟插值 类型2
-- 每一次调用都会在delay时间后被封装成一个命令。
-- 但是如果调用2发生时，调用1还在delay中，还没开始执行命令，那么调用2会删除调用1
-- 如果调用2发生时，调用1的delay已经结束，并且已经开始执行命令，那么调用2不会打断调用1的命令。只是delay等待执行命令。
-- 注意，delay时间必须要大于duration时间（按说也是理应如此）

function BossSlider:DelayLerpProgress2(toProgress, delay, duration, onLerp, onLerpEnd)
    local command = {
        to = toProgress,
        delay = delay,
        duration = duration,
        onLerp = onLerp,
        onLerpEnd = onLerpEnd,
    }

    if not isNull(self.delayCommandCo2) then
        cs_coroutine.stop(self.delayCommandCo2)
        self.delayCommandCo2 = nil
    end

    self.delayCommandCo2 = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(delay))
        self:LerpProgress(command.to, command.duration, self.defaultCurve, command.onLerp, command.onLerpEnd)
        self.delayCommandCo2 = nil
    end)
end
--@endregion

--@region 弯曲血条实现
--- 获取端点的坐标和旋转
function BossSlider:GetEndPoint()
    if self.isReverseMode then
        local position = self.uiLineRenderer.Points[self.uiLineRenderer.Points.Length - 1]
        local angle = 0
        if self.progress <= (1 - self.quaterPercentage) then
            angle = 0
        else
            angle = (self.progress - (1 - self.quaterPercentage)) / self.quaterPercentage * quaterAngle
        end
        return {[0] = position, [1] = angle}
    else
        local position = self.uiLineRenderer.Points[0]
        local angle = 0
        if self.progress >= self.quaterPercentage then
            angle = 0
        else
            angle = (self.quaterPercentage - self.progress) / self.quaterPercentage * quaterAngle
        end
        return {[0] = position, [1] = angle}
    end
end

--- 根据进度计算端点的位置
---@param progress number (range(0,1))
function BossSlider:CalculateEndPoint(progress)
    if self.isReverseMode then
        progress = 1 - progress
    end

    if progress > self.quaterPercentage then
        local point = self.lineStartPos + Vector2.right * self.lineLength * (progress - self.quaterPercentage) / (1 - self.quaterPercentage)
        return point
    else
        local angle = (self.quaterPercentage - progress) / self.quaterPercentage * quaterAngle
        local deltaRotation = Quaternion.AngleAxis(-angle, Vector3.forward)
        local linkDir = self.lineStartPos - self.circleCenterPos
        linkDir = Quaternion.MulVec3(deltaRotation, Vector3.New(linkDir.x, linkDir.y, 0))
        local point = self.circleCenterPos + linkDir
        return point
    end
end

--- 计算slider的控制点，并将控制点设置给lineRenderer。这样就显示出来了
function BossSlider:SetPoints()
    self.pointList:Clear()
    self:InitKeyPointPos()
    self:InitPointList()
    self.uiLineRenderer.Points = self.pointList:ToArray()
    self.uiLineRenderer.LineThickness = self.width
end

--- 计算关键点坐标
function BossSlider:InitKeyPointPos()
    local centerPos = self.originPos:Clone()
    centerPos.x = centerPos.x + self.width * 0.5 + self.quaterRadiur
    self.circleCenterPos = centerPos:Clone()

    local lineStartPos = self.circleCenterPos:Clone()
    lineStartPos.y = lineStartPos.y - self.quaterRadiur
    self.lineStartPos = lineStartPos:Clone()

    local lineEndPos = self.lineStartPos:Clone()
    lineEndPos.x = lineEndPos.x + self.lineLength
    self.lineEndPos = lineEndPos:Clone()
end

--- 根据关键点计算控制点坐标，并保存到pointList
function BossSlider:InitPointList()
    -- 添加line point
    self.pointList:Add(self.lineEndPos)
    self.pointList:Add(self.lineStartPos)
    -- 添加 quater point
    local linkDir = self.lineStartPos - self.circleCenterPos
    local segmentAngle = quaterAngle / quaterPointNum
    local segmentRotation = Quaternion.AngleAxis(-segmentAngle, Vector3.forward)

    for i = 1, quaterPointNum, 1 do
        linkDir = Quaternion.MulVec3(segmentRotation, Vector3.New(linkDir.x, linkDir.y, 0))
        local point = self.circleCenterPos + linkDir
        self.pointList:Add(point)
    end
end

--- 设置slider上的当前端点位置，并将端点以前的控制点都拉到端点位置
---@param endPoint Vector2 端点坐标
function BossSlider:SetEndPoint(endPoint)
    local points = self.uiLineRenderer.Points
    if self.isReverseMode then
        -- 逆向模式
        for i = 0, points.Length - 1, 1 do
            local point = points[i]
            if endPoint.x > self.pointList[i].x then
                points[i] = endPoint
            else
                points[i] = self.pointList[i]
            end
        end
    else
        -- 正向模式
        for i = 0, points.Length - 1, 1 do
            local point = points[i]
            if endPoint.x > self.pointList[i].x then
                points[i] = self.pointList[i]
            else
                points[i] = endPoint
            end
        end
    end
    self.uiLineRenderer:SetAllDirty()
end
--@endregion

return BossSlider